```java[]
import java.util.Deque;
import java.util.ArrayDeque;

class Solution {
    public int maximalAreaOfSubMatrixOfAll1(int[][] matrix) {
        int n = matrix.length;
            int m = matrix[0].length;
       int ans = 0;
            int[] heights = new int[m];
            for (int i = 0; i < n; i++) {
                Deque<Integer> st = new ArrayDeque<>();
                for (int j = 0; j < m; j++) {
                    if (matrix[i][j] == 0) {
                        heights[j] = 0;
                    } else {
                        heights[j]++;
                    }
                    while (!st.isEmpty() && heights[j] <= heights[st.peek()]) {
                        int pop = st.pop();
                        int pse = st.isEmpty() ? -1 : st.peek();
                        int nse = j;
                        int val = nse - pse - 1;
                        val = val * heights[pop];
                        ans = Math.max(ans, val);
                    }
                    st.push(j);
                }
                while (!st.isEmpty()) {
                    int pop = st.pop();
                    int pse = st.isEmpty() ? -1 : st.peek();
                    int nse = m;
                    int val = nse - pse - 1;
                    val = val * heights[pop];
                    ans = Math.max(ans, val);
                }
            }
            return ans;
    }
}
